mapper.sql:
WHERE w.member_id = #{childId}
AND p.status = 'SUCCESS'
AND p.created_at >= #{from}
AND p.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)

mapper.select:
SELECT
COALESCE(SUM(CASE WHEN t.type = 'DEPOSIT' AND fw.member_id = #{childId}
                  THEN t.amount ELSE 0 END), 0) AS deposit_amount,
COALESCE(SUM(CASE WHEN t.type = 'SAVING' AND fw.member_id = #{childId}
                  THEN t.amount ELSE 0 END), 0) AS saving_amount,
COALESCE(SUM(CASE WHEN t.type = 'QUEST_REWARD' AND tw.member_id = #{childId}
                  THEN t.amount ELSE 0 END), 0) AS earned_amount,
COALESCE(SUM(CASE WHEN t.type = 'QUEST_REWARD' AND tw.member_id = #{childId}
                  THEN 1 ELSE 0 END), 0) AS quest_reward_count,

COUNT(DISTINCT CASE WHEN t.type = 'SAVING' AND fw.member_id = #{childId}
                    THEN t.to_wallet_id END) AS saving_product_count,
COALESCE(SUM(CASE WHEN t.type = 'SAVING' AND fw.member_id = #{childId}
                  THEN 1 ELSE 0 END), 0) AS saving_payment_count,
COUNT(DISTINCT CASE WHEN t.type = 'DEPOSIT' AND fw.member_id = #{childId}
                    THEN t.to_wallet_id END) AS deposit_product_count,
COALESCE(SUM(CASE WHEN t.type = 'DEPOSIT' AND fw.member_id = #{childId}
                  THEN 1 ELSE 0 END), 0) AS deposit_payment_count
FROM T_WLT_TRF_L t
JOIN T_WLT_BASE_M fw ON fw.id = t.from_wallet_id
JOIN T_WLT_BASE_M tw ON tw.id = t.to_wallet_id
WHERE t.status = 'COMPLETED'
AND (fw.member_id = #{childId} OR tw.member_id = #{childId})

AND COALESCE(t.updated_at, t.created_at) >= #{from}
AND COALESCE(t.updated_at, t.created_at) < DATE_ADD(#{to}, INTERVAL 1 DAY)
